dependency.expression:
min(/Linux by Zabbix agent/system.cpu.load[all,avg1],5m)/last(/Linux by Zabbix agent/system.cpu.num)>{$LOAD_AVG_PER_CPU.MAX.WARN}
and last(/Linux by Zabbix agent/system.cpu.load[all,avg5])>0
and last(/Linux by Zabbix agent/system.cpu.load[all,avg15])>0

parameters.parameter:
var newvalue;
switch(value) {
  case "unknown":
	newvalue = 0;
	break;
  case "notpresent":
	newvalue = 1;
	break;
  case "down":
	newvalue = 2;
	break;
  case "lowerlayerdown":
	newvalue = 3;
	break;
  case "testing":
	newvalue = 4;
	break;
  case "dormant":
	newvalue = 5;
	break;
  case "up":
	newvalue = 6;
	break;  default:
	newvalue = "Problem parsing interface operstate in JS";
}
return newvalue;

output = JSON.parse(value).map(function(net){
    return {
        "{#IFNAME}": net.Name,
        "{#IFDESCR}": net.Description,
        "{#IFALIAS}": net.NetConnectionID,
        "{#IFGUID}": net.GUID
    }})
return JSON.stringify({"data": output})

trigger.expression:
min(/Linux by Zabbix agent/system.cpu.load[all,avg1],5m)/last(/Linux by Zabbix agent/system.cpu.num)>{$LOAD_AVG_PER_CPU.MAX.WARN}
and last(/Linux by Zabbix agent/system.cpu.load[all,avg5])>0
and last(/Linux by Zabbix agent/system.cpu.load[all,avg15])>0
